// MineBench: a choo-choo train. Steam loco, tender, three coaches, on a rolling
// diorama with a station, telegraph line, trees and a smoke plume.
// Track runs along X, nose points to +X. Rails at z=125 and z=131 (y=2).
// Wheel centres y=7, radius 4. Boiler axis y=14, z=128.

const CZ = 128;

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

// Filled disc in the plane x = const. pick(d, dy, dz) returns a block type or null.
function discX(x, cy, cz, r, pick) {
  const R = Math.ceil(r);
  for (let dy = -R; dy <= R; dy++) for (let dz = -R; dz <= R; dz++) {
    const d = Math.sqrt(dy * dy + dz * dz);
    if (d > r + 0.3) continue;
    const t = pick(d, dy, dz);
    if (t) block(x, cy + dy, cz + dz, t);
  }
}

// Filled disc in the plane y = const. pick(d, dx, dz).
function discY(y, cx, cz, r, pick) {
  const R = Math.ceil(r);
  for (let dx = -R; dx <= R; dx++) for (let dz = -R; dz <= R; dz++) {
    const d = Math.sqrt(dx * dx + dz * dz);
    if (d > r + 0.3) continue;
    const t = pick(d, dx, dz);
    if (t) block(cx + dx, y, cz + dz, t);
  }
}

// Filled disc in the plane z = const (wheels). pick(d, dx, dy).
function discZ(z, cx, cy, r, pick) {
  const R = Math.ceil(r);
  for (let dx = -R; dx <= R; dx++) for (let dy = -R; dy <= R; dy++) {
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d > r + 0.3) continue;
    const t = pick(d, dx, dy);
    if (t) block(cx + dx, cy + dy, z, t);
  }
}

// ---------- terrain ----------
function inStation(x, z) { return x >= 96 && x <= 150 && z >= 102 && z <= 121; }

// Ground top height. Flat around the track, hills rolling away from it.
function groundTop(x, z) {
  if (inStation(x, z)) return 0;
  const d = Math.abs(z - CZ);
  const s = clamp((d - 8) / 14, 0, 1);
  const h = 0.5 + 0.25 * Math.sin(x * 0.09) + 0.25 * Math.cos(z * 0.13 + x * 0.03);
  return Math.floor(9 * h * s);
}

for (let x = 16; x <= 240; x++) {
  for (let z = 72; z <= 184; z++) {
    const top = groundTop(x, z);
    if (inStation(x, z)) {
      block(x, 0, z, 'cobblestone');
      continue;
    }
    if (top === 0) {
      block(x, 0, z, Math.abs(z - CZ) <= 5 ? 'stone' : 'grass_block');
      continue;
    }
    for (let y = 0; y < top; y++) block(x, y, z, 'dirt');
    block(x, top, z, 'grass_block');
  }
}

// ---------- track ----------
for (let x = 24; x <= 232; x += 2) box(x, 1, 122, x, 1, 134, 'oak_planks');
box(24, 2, 125, 232, 2, 125, 'iron_block');
box(24, 2, 131, 232, 2, 131, 'iron_block');

// ---------- station ----------
box(100, 1, 113, 136, 1, 118, 'stone_bricks');   // raised platform
// house
box(104, 1, 104, 120, 6, 110, 'bricks');
for (let z = 104; z <= 110; z++) {
  const top = 7 + Math.min(z - 104, 110 - z);
  box(103, 7, z, 121, top, z, 'black_wool');
}
box(104, 6, 104, 120, 6, 104, 'gold_block');     // fascia sign band
box(107, 3, 104, 108, 4, 104, 'glass');
box(112, 3, 104, 113, 4, 104, 'glass');
box(117, 3, 104, 118, 4, 104, 'glass');
box(108, 3, 110, 109, 4, 110, 'glass');
box(116, 3, 110, 117, 4, 110, 'glass');
box(112, 1, 110, 113, 3, 110, 'oak_planks');     // door
// lamp posts along the platform edge
for (const lx of [104, 120, 136]) {
  box(lx, 2, 113, lx, 5, 113, 'oak_log');
  block(lx, 6, 113, 'glowstone');
}
// benches
box(104, 2, 117, 107, 2, 117, 'oak_planks');
box(124, 2, 117, 129, 2, 117, 'oak_planks');
// waiting passengers
function person(x, z, shirt) {
  block(x, 2, z, 'black_wool');
  block(x, 3, z, shirt);
  block(x, 4, z, shirt);
  block(x, 5, z, 'orange_wool');
}
person(112, 115, 'red_wool');
person(116, 116, 'blue_wool');
person(124, 114, 'green_wool');
person(130, 116, 'red_wool');
// water tower
for (const [lx, lz] of [[140, 104], [144, 104], [140, 110], [144, 110]]) box(lx, 1, lz, lx, 9, lz, 'oak_log');
discY(10, 142, 107, 3, () => 'iron_block');
discY(11, 142, 107, 3, () => 'iron_block');
discY(12, 142, 107, 3, () => 'iron_block');
discY(13, 142, 107, 3, () => 'iron_block');
discY(14, 142, 107, 2, () => 'iron_block');
discY(15, 142, 107, 1, () => 'iron_block');

// ---------- trees ----------
function tree(x, z, H) {
  const y0 = groundTop(x, z) + 1;
  const trunkTop = y0 + H;
  for (let y = y0; y < trunkTop; y++) block(x, y, z, 'oak_log');
  const cy = trunkTop + 1;
  const R = 3.2 + rng() * 0.8;
  const S = Math.ceil(R) + 1;
  for (let dx = -S; dx <= S; dx++) for (let dy = -S; dy <= S; dy++) for (let dz = -S; dz <= S; dz++) {
    if (dx * dx + dy * dy + dz * dz > R * R + (rng() - 0.5) * 2.5) continue;
    if (dx === 0 && dz === 0 && cy + dy <= trunkTop) continue;
    block(x + dx, cy + dy, z + dz, 'oak_leaves');
  }
}
