tree(178, 150, 5);

// ---------- telegraph line along z=141 ----------
for (let px = 24; px <= 232; px += 16) {
  const y0 = groundTop(px, 141) + 1;
  box(px, y0, 141, px, y0 + 6, 141, 'oak_log');
  box(px, y0 + 5, 140, px, y0 + 5, 142, 'oak_planks');
}
for (let px = 24; px < 232; px += 16) {
  const ya = groundTop(px, 141) + 6;
  const yb = groundTop(px + 16, 141) + 6;
  line(px, ya, 141, px + 16, yb, 141, 'black_wool');
}

// ---------- the train ----------
// one wheel: a disc of radius 4 centred at (cx, 7), two thick, at z = zA and zB
function wheel(cx, zA, zB) {
  for (const z of [zA, zB]) {
    discZ(z, cx, 7, 4, (d, u, v) => {
      if (d <= 1) return 'gold_block';
      if (d >= 3.2) return 'iron_block';
      if (u === 0 || v === 0) return 'red_wool';
      return 'black_wool';
    });
  }
}
function axle(cx) {
  wheel(cx, 124, 125);
  wheel(cx, 131, 132);
}

// --- locomotive, x 172..218 ---
box(172, 5, 126, 216, 6, 130, 'gray_wool');              // chassis
box(172, 11, 120, 216, 11, 121, 'iron_block');           // side skirts
box(172, 11, 135, 216, 11, 136, 'iron_block');

// cab
box(172, 9, 122, 185, 9, 134, 'gray_wool');              // footplate
box(172, 10, 122, 172, 21, 134, 'red_wool');             // back wall
box(185, 10, 122, 185, 21, 134, 'red_wool');             // front wall
box(173, 10, 122, 184, 21, 122, 'red_wool');             // left side
box(173, 10, 134, 184, 21, 134, 'red_wool');             // right side
box(175, 14, 122, 179, 18, 122, 'glass');
box(181, 14, 122, 184, 18, 122, 'glass');
box(175, 14, 134, 179, 18, 134, 'glass');
box(181, 14, 134, 184, 18, 134, 'glass');
box(170, 22, 120, 188, 22, 136, 'black_wool');            // roof

// boiler, axis along x at y=14, z=128
for (let x = 186; x <= 216; x++) {
  const band = x === 189 || x === 201 || x === 212;
  discX(x, 14, CZ, x === 216 ? 5.2 : 6, (d, dy, dz) => {
    if (x === 216) return d <= 2.5 ? 'iron_block' : 'black_wool';   // smokebox door
    if (band) return 'iron_block';
    if (dy >= 5) return 'gray_wool';                              // lit top
    if (Math.abs(dz) >= 5 && Math.abs(dy) <= 1) return 'gold_block'; // pinstripe
    return 'black_wool';
  });
}

// steam dome, bell, chimney
discY(20, 198, CZ, 2.6, () => 'gold_block');
discY(21, 198, CZ, 2.0, () => 'gold_block');
discY(22, 198, CZ, 1.2, () => 'gold_block');
block(198, 23, CZ, 'gold_block');
discY(21, 204, CZ, 1, () => 'gold_block');
block(204, 22, CZ, 'gold_block');
for (let y = 20; y <= 26; y++) {
  const r = y <= 22 ? 1.5 : (y <= 25 ? 2 : 2.6);
  discY(y, 210, CZ, r, () => 'black_wool');
}
discY(27, 210, CZ, 3, () => 'iron_block');

// cowcatcher: slatted wedge, low at the nose
for (let x = 210; x <= 216; x++) {
  const top = 3 + Math.floor((216 - x) * 0.8);
  for (let y = 3; y <= top; y++) for (let z = 122; z <= 134; z += 2) block(x, y, z, 'iron_block');
}
