block(218, 14, CZ, 'glowstone');

// driving wheels and rods
axle(180); axle(189); axle(198); axle(207);
box(180, 7, 123, 207, 7, 123, 'iron_block');
box(180, 7, 133, 207, 7, 133, 'iron_block');

// --- tender, x 148..168 ---
box(148, 5, 126, 168, 6, 130, 'gray_wool');
box(148, 8, 122, 168, 14, 134, 'black_wool');
box(148, 11, 121, 168, 11, 121, 'red_wool');
box(148, 11, 135, 168, 11, 135, 'red_wool');
box(148, 15, 122, 168, 15, 134, 'black_wool');
box(154, 16, 125, 162, 16, 131, 'black_wool');
for (let x = 148; x <= 168; x++) for (let z = 122; z <= 134; z++) {
  if (rng() < 0.12) block(x, 15, z, 'gray_wool');
}
axle(153); axle(163);

// coupler, loco to tender
box(169, 6, 127, 171, 6, 129, 'iron_block');

// --- coaches ---
function bellows(g0, g1) {
  box(g0, 6, 127, g1, 6, 129, 'iron_block');             // coupler
  box(g0, 8, 125, g1, 13, 131, 'black_wool');            // bellows
}
function coach(x0, x1, body) {
  box(x0, 5, 126, x1, 6, 130, 'gray_wool');              // chassis
  box(x0, 9, 122, x1, 15, 134, body);                    // body
  for (let x = x0; x <= x1; x++) {
    discX(x, 15, CZ, 6.5, (d, dy, dz) => {
      if (dy < 0) return null;
      if (Math.abs(dz) >= 6) return body;
      return dy >= 3 ? 'white_wool' : body;              // white arched roof
    });
  }
  box(x0, 14, 122, x1, 14, 122, 'gold_block');           // window-line trim
  box(x0, 14, 134, x1, 14, 134, 'gold_block');
  for (let wx = x0 + 3; wx + 2 <= x1 - 3; wx += 6) {
    box(wx, 11, 122, wx + 2, 13, 122, 'glass');
    box(wx, 11, 134, wx + 2, 13, 134, 'glass');
  }
  axle(x0 + 6);
  axle(x1 - 6);
}
