bellows(147, 147);

// ---------- smoke plume from the chimney ----------
for (let i = 0; i < 12; i++) {
  const ox = Math.round(210 - 2.6 * i - rng() * 2);
  const oy = Math.round(30 + 1.5 * i + rng());
  const oz = Math.round(CZ + (rng() - 0.5) * 2.5);
  const r = 1.8 + 0.4 * i + rng();
  const R = Math.ceil(r);
  for (let dx = -R; dx <= R; dx++) for (let dy = -R; dy <= R; dy++) for (let dz = -R; dz <= R; dz++) {
    if (dx * dx + dy * dy + dz * dz > r * r) continue;
    block(ox + dx, oy + dy, oz + dz, i > 7 && rng() < 0.6 ? 'gray_wool' : 'white_wool');
  }
}
